    }
  },
  required: ['path'],
  additionalProperties: false
};

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata for a file under the workspace data directory: its relative path, byte size, and lowercase extension. Does not read or expose file contents. Rejects path traversal and missing files.',
      inputSchema: FILE_METADATA_INPUT_SCHEMA
    }
  ];
}

function validateFileMetadataInput(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  const keys = Object.keys(args);
  if (keys.length > 1 || !('path' in args)) {
    // strict: only path allowed
    if (!('path' in args)) throw new Error('Missing required argument: path');
    throw new Error('Unknown argument(s): ' + keys.filter(k => k !== 'path').join(', '));
  }
  if (typeof args.path !== 'string') {
    throw new Error('Argument "path" must be a string');
  }
  if (args.path.length === 0) {
    throw new Error('Argument "path" must not be empty');
  }
}

